import{_ as e,c as t,o as r,b2 as n}from"./chunks/framework.CUhoHPxN.js";const m=JSON.parse('{"title":"C7Dialog 弹窗 / 抽屉","description":"","frontmatter":{},"headers":[],"relativePath":"docs/frontend/components/通用组件/c7-dialog.md","filePath":"docs/frontend/components/通用组件/c7-dialog.md"}'),d={name:"docs/frontend/components/通用组件/c7-dialog.md"};function s(c,o,a,g,l,i){return r(),t("div",null,[...o[0]||(o[0]=[n('<h1 id="c7dialog-弹窗-抽屉" tabindex="-1">C7Dialog 弹窗 / 抽屉 <a class="header-anchor vp-link" href="#c7dialog-弹窗-抽屉" aria-label="Permalink to &quot;C7Dialog 弹窗 / 抽屉&quot;">​</a></h1><p>在 <strong><code>ElDialog</code> / <code>ElDrawer</code></strong> 上统一 <strong>footer、异步确定、双 v-model（<code>modelValue</code> + 兼容 <code>visible</code>）</strong> 与 <strong><code>modalProps</code> 透传</strong>。</p><p><strong>源码</strong>：<code>quick-ui/src/packages/C7Dialog/index.vue</code><br><strong>Dev 页</strong>：开发服务器启动后访问 <code>/dev/c7-dialog-e2e</code></p><h2 id="功能概要" tabindex="-1">功能概要 <a class="header-anchor vp-link" href="#功能概要" aria-label="Permalink to &quot;功能概要&quot;">​</a></h2><ul><li><strong><code>mode</code></strong>：<code>dialog</code> | <code>drawer</code>。</li><li><strong>标题</strong>：<code>title</code> 文案 prop；需完全自定义标题区时使用 <strong><code>#title</code></strong> 插槽（内部映射为 Element Plus 的 <strong><code>#header</code></strong>）。</li><li><strong>显隐</strong>：优先 <strong><code>v-model:modelValue</code></strong>；否则 <strong><code>v-model:visible</code></strong>。关闭时 <strong>同时</strong> <code>update:modelValue</code> 与 <code>update:visible</code> 为 <strong><code>false</code></strong>。二者同时传入且不一致时，开发环境 <strong>warn</strong>，以 <strong><code>modelValue</code></strong> 为准。</li><li><strong>默认 footer</strong>：<code>footer=true</code> 且无 <strong><code>#footer</code></strong> 时，左侧 <strong><code>#extra</code></strong>，右侧 <strong>取消 / 确定</strong>；提供 <strong><code>#footer</code></strong> 时 <strong>仅渲染插槽</strong>。</li><li><strong><code>onConfirm</code></strong>：点击确定 <strong>await</strong>；<strong>resolve</strong> 后自动关闭；<strong>reject/throw</strong> 不关、无内置 <strong><code>ElMessage</code></strong>。确定钮 <strong>loading</strong>：<strong><code>confirmLoading !== undefined</code></strong> 时以外部为准，否则为内部 <strong><code>onConfirm</code> pending</strong>。</li><li><strong>无 <code>onConfirm</code></strong>：依次 <strong><code>emit(&#39;confirm&#39;)</code>、<code>emit(&#39;submit&#39;)</code></strong>，不自动关窗。</li><li><strong><code>@cancel</code></strong>：点击取消时触发并已关闭。</li><li><strong>卸载</strong>：若仍打开，<strong>双 emit <code>false</code></strong> 同步父状态。</li><li><strong>透传</strong>：根上非监听属性与 <strong><code>modalProps</code></strong> 合并进壳层，<strong>后合并覆盖</strong>（调用方优先）。</li></ul><h2 id="与全局注册" tabindex="-1">与全局注册 <a class="header-anchor vp-link" href="#与全局注册" aria-label="Permalink to &quot;与全局注册&quot;">​</a></h2><p>在 <code>main.js</code> 已调用 <code>installPackages(app)</code> 时，模板中可直接使用 <code>&lt;c7-dialog /&gt;</code>（或 <code>&lt;C7Dialog /&gt;</code>）。</p><h2 id="相关规格" tabindex="-1">相关规格 <a class="header-anchor vp-link" href="#相关规格" aria-label="Permalink to &quot;相关规格&quot;">​</a></h2><p>OpenSpec 变更：<code>openspec/changes/ui-c7-dialog/specs/ui-c7-dialog/spec.md</code></p>',9)])])}const u=e(d,[["render",s]]);export{m as __pageData,u as default};
